content.text:
{
  "name": "Sensirion EK-H4 温湿度传感器多路复用盒",
  "name_en": "Sensirion EK-H4 humidity and temperature sensor multiplexer box",
  "manufacturer": "Sensirion",
  "description": "用于通过串口连接并读取最多 4 路 Sensirion 温湿度传感器的多路复用采集盒。在实验中可用于环境温度、相对湿度和露点的多通道监测。",
  "description_en": "A multiplexer box that connects over a serial port and reads up to four Sensirion humidity and temperature sensor channels. It is used in laboratory setups for multi-channel monitoring of temperature, relative humidity, and dew point.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化 EK-H4 设备通信并准备采集。",
      "description_en": "Initialize communication with the EK-H4 and prepare it for data acquisition."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "读取指定通道或全部通道的温度。",
      "description_en": "Read temperature from a specified channel or from all channels."
    },
    {
      "action_name": "auto-get_humidity",
      "description": "读取指定通道或全部通道的相对湿度。",
      "description_en": "Read relative humidity from a specified channel or from all channels."
    },
    {
      "action_name": "auto-get_dew_point",
      "description": "读取指定通道或全部通道的露点。",
      "description_en": "Read dew point from a specified channel or from all channels."
    }
  ],
  "tag_hints": [
    "humidity measurement",
    "temperature measurement",
    "dew point",
    "sensor multiplexer",
    "environmental monitoring",
    "serial communication",
    "Sensirion"
  ]
}

